    "problems.section_label": "THE PROBLEM",
    "problems.title": "Hiring informal workers today is broken",
    "problems.subtitle": "Before DireSkill, every hire was a gamble — no credentials, no receipts, no accountability.",
    "problems.1.problem": "Workers advertise using hand-written posters.",
    "problems.1.solution": "Search verified professionals by skill and district instantly.",
