    "problems.2.problem": "No way to verify a worker's real identity.",
    "problems.2.solution": "Every worker passes Ethiopia's Fayda Digital ID verification.",
    "problems.2.benefit": "Know exactly who is entering your home.",
    "problems.3.problem": "Verbal agreements lead to disputes with no proof.",
