    "verify.section_label": "WORKER VERIFICATION",
    "verify.title": "Trust starts with verified identity",
    "verify.subtitle": "DireSkill is the first platform in Dire Dawa to require Fayda Digital ID verification for all workers.",
    "verify.step1.title": "Worker Submits Fayda ID",
    "verify.step1.desc": "Worker uploads their Ethiopia Fayda National Digital ID document during registration.",
    "verify.step2.title": "Admin Reviews & Verifies",
    "verify.step2.desc": "Our admin team audits the document for authenticity before granting platform access.",
    "verify.step3.title": "Verified Badge Earned",
    "verify.step3.desc": "Once verified, a permanent ✓ Fayda Verified badge appears on the worker's profile.",
    "verify.step4.title": "Clients Hire With Confidence",
    "verify.step4.desc": "You see exactly who you're hiring — name, photo, and verified identity — before you commit.",

    "contract.section_label": "DIGITAL CONTRACTS & PAYMENTS",
    "contract.title": "Every job. Documented. Protected. Paid.",
    "contract.subtitle": "No more verbal agreements that lead to disputes. DireSkill creates accountability at every step.",
    "contract.step1.title": "Client Hires Worker",
    "contract.step1.desc": "Client sends a formal hiring invitation with job title, budget, and terms.",
    "contract.step2.title": "Contract Created",
    "contract.step2.desc": "A digital service contract is automatically generated from the job details.",
    "contract.step3.title": "Both Parties Sign",
    "contract.step3.desc": "Client and worker both digitally sign the agreement before work begins.",
    "contract.step4.title": "Work Begins",
    "contract.step4.desc": "The job starts only after the contract is fully signed by both parties.",
    "contract.step5.title": "Secure Payment via Chapa",
    "contract.step5.desc": "Client pays through Chapa's secure gateway. Funds are released upon job confirmation.",
    "contract.step6.title": "Payment Confirmed",
    "contract.step6.desc": "Worker receives a complete payment record and reputation points.",
    "contract.chapa_note": "All payments processed by Chapa — Ethiopia's most trusted payment gateway.",

    "faq.section_label": "FAQ",
    "faq.title": "Answers to your questions",
    "faq.subtitle": "Everything you need to know before signing up.",
    "faq.1.q": "How does Fayda ID verification work?",
    "faq.1.a": "Workers upload their Ethiopia Fayda National Digital ID during registration. Our admin team manually reviews and authenticates the document. Once approved, a verified badge appears permanently on their profile. Unverified workers cannot access the platform's hiring features.",
    "faq.2.q": "How are digital contracts created?",
    "faq.2.a": "When a client sends a hiring invitation, DireSkill automatically generates a digital service contract from the job details (title, budget, scope, and terms). Both the client and worker review and digitally sign the contract before any work begins.",
    "faq.3.q": "How does the Chapa payment work?",
    "faq.3.a": "After job completion, the client pays the agreed amount securely through Chapa, Ethiopia's trusted payment gateway. The transaction is recorded in both the client and worker's payment history and is linked to the digital contract as proof of payment.",
    "faq.4.q": "Can workers negotiate prices?",
    "faq.4.a": "Yes. Workers can communicate pricing preferences through in-app messaging before a formal hiring invitation is created. Once both parties agree on terms, a contract is drafted with the negotiated amount.",
    "faq.5.q": "What happens if there is a dispute?",
    "faq.5.a": "Both clients and workers can raise a dispute from within the contract details page. Our admin team reviews the dispute, examines the contract terms and any uploaded evidence, and issues a binding platform decision within 48 hours.",
    "faq.6.q": "How do workers improve their reputation?",
    "faq.6.a": "Every completed, paid job allows the client to leave a verified rating and written review. Workers accumulate ratings over time, building a public reputation score visible to all future clients. High-rated workers appear higher in search results.",

