    "testimonials.title": "ደንበኞቻችን ምን ይላሉ",
    "testimonials.subtitle": "በድሬዳዋ ላይ እምነትን መገንባት፣ በአንድ ስኬታማ ስራ በአንድ ጊዜ።",

    "testimonial.1.name": "አህመድ ተስፋዬ",
    "testimonial.1.role": "የንብረት አስተዳዳሪ",
    "testimonial.1.text": "DireSkill ህንፃዎቼን የማስተዳድርበትን መንገድ ሙሉ በሙሉ ቀይሮታል። በደቂቃዎች ውስጥ የተረጋገጠ የቧንቧ ሰራተኛ ማግኘት ህይወት አዳኝ ነው።",
    "testimonial.2.name": "ሙና ኢብራሂም",
    "testimonial.2.role": "የቤት እመቤት",
    "testimonial.2.text": "ሰራተኞችን ስቀጥር ስለ ደህንነት እጨነቅ ነበር። አሁን በዲጂታል ውል እና በማንነት ማረጋገጫ 100% ደህንነት ይሰማኛል።",
    "testimonial.3.name": "ዳዊት በርሀኑ",
    "testimonial.3.role": "የንግድ ስራ ባለቤት",
    "testimonial.3.text": "በዚህ መድረክ ላይ ያሉ ባለሙያዎች ጥራት ተወዳዳሪ የለውም። ቀልጣፋ፣ የተረጋገጠ እና ሁልጊዜም ሙያዊ።",
    "testimonial.4.name": "ሰላማዊት ገ.",
    "testimonial.4.role": "የሱቅ ስራ አስኪያጅ",
    "testimonial.4.text": "በቀዝራ የኤሌክትሪክ ሰራተኛ ለማግኘት ፈጣኑ መንገድ። የደረጃ አሰጣጥ ስርዓቱ ትክክለኛውን ሰው ለመምረጥ በጣም ይረዳል።",
    "testimonial.5.name": "ዮናስ ብ.",
    "testimonial.5.role": "የምግብ ቤት ባለቤት",
    "testimonial.5.text": "በDireSkill በኩል ያገኘሁት የቤት አጨራረስ ስራ ልዩ ነበር። ንጹህ፣ ሙያዊ እና በሰዓቱ የተጠናቀቀ።",
    "testimonial.6.name": "ሃና ተ.",
    "testimonial.6.role": "የጥምረት ትምህርት ቤት ዳይሬክተር",
    "testimonial.6.text": "በመጨረሻ ሰራተኞች የሚረጋገጡበት የገበያ ቦታ አገኘን። ለትምህርት ቤታችን ጥገና ሁሉ የአእምሮ ሰላም ይሰጠናል።",

