    "verify.step1.desc": "ሰራተኛ ወቅቱ ምዝገባ ኢትዮጵያ ፋይዳ ዲጂታል መታወቂያ ሰነድ ይጭናል።",
    "verify.step2.title": "አስተዳዳሪ ያረጋግጣሉ",
    "verify.step2.desc": "ቡድናችን ሰነዱን ፕላትፎርሙን ከመስጠታቸው በፊት ለትክክለኛነት ምርምራ ያደርጋሉ።",
    "verify.step3.title": "የተረጋገጠ ምልክት ይሰጣሉ",
    "verify.step3.desc": "ሲረጋጋ ∓ ፋይዳ ተረጋግጧል ምልክት ዘላቂ ሆኖ ፕሮፋይሉ ላይ ይታያሉ።",
    "verify.step4.title": "ደንበኞች በዕምነት ይቀጥራሉ",
    "verify.step4.desc": "ቃል ሳይቃሙ ማን እንደሚቀጥሩ — ስም፣ ፎቶ እና ማንነት — ያያሉ።",

    "contract.section_label": "ዲጂታል ውሎች እና ክፍያዎች",
    "contract.title": "ሁሉም ስራ። ተመዝጋቦ። ጠብቆ። ተከፍሎ።",
    "contract.subtitle": "ምንም ቃላዊ ስምምነቶች ወደ ክርክር አይመሩም። DireSkill ተጠያቂነትን ይፈጥራሉ።",
    "contract.step1.title": "ደንበኛ ሰራተኛ ይቀጥራሉ",
    "contract.step1.desc": "ደንበኛ የስራ ርዕስ፣ ደምወዝ እና ሁኔታዎች ያለው ቅጥር ጥሪ ይላካሉ።",
    "contract.step2.title": "ውል ተፈጠረ",
    "contract.step2.desc": "ዲጂታል ሰርቪስ ውል ከስራ ዝርዝሮቹ በራስ-ሰር ይፈጠራሉ።",
    "contract.step3.title": "ሁለቱም ይፈርማሉ",
    "contract.step3.desc": "ደንበኛ እና ሰራተኛ ሥራ ከመጀመሩ በፊት ዲጂታሉ ስምምነት ይፈርማሉ።",
    "contract.step4.title": "ስራ ይጀምራሉ",
    "contract.step4.desc": "ሁለቱም ወገን ሲፈርሙ ብቻ ስራ ይጀምራሉ።",
    "contract.step5.title": "ቻፓ ደህንነቱ የተጠበቀ ክፍያ",
    "contract.step5.desc": "ደንበኛ በቻፓ ደህንነቱ ተጠብቆ ይከፍላሉ። ስራ ሲረጋ ልቀት ይደረጋሉ።",
    "contract.step6.title": "ክፍያ ተረጋጋ",
    "contract.step6.desc": "ሰራተኛ ሙሉ ክፍያ መዝገብ ይቀበላሉ።",
    "contract.chapa_note": "ሁሉም ክፍያዎች ቻፓ — ኢትዮጵያ ዋና ክፍያ ቦይ — ያካሄዳሉ።",

    "faq.section_label": "ተዘውትሮ የሚጠየቁ ጥያቄዎች",
    "faq.title": "ለጥያቄዎቻቸዎ መልስ",
    "faq.subtitle": "ለመመዝገብ ከመሄዳቸዎ በፊት ሁሉም የሚያስፈልጉ ዝርዝሮች።",
    "faq.1.q": "ፋይዳ መታወቂያ ማረጋገጫ እንዴት ይሰራል?",
    "faq.1.a": "ሰራተኞች ምዝገባ ኢትዮጵያ ፋይዳ ዲጂታል ብሄራዊ መታወቂያ ይጭናሉ። አስተዳዳሪዎቻችን ሰነዱን ሲመረምሩ ሲረጋ ምልክት ይሰጣሉ።",
    "faq.2.q": "ዲጂታል ውሎች እንዴት ይፈጠራሉ?",
    "faq.2.a": "ደንበኛ ቅጥር ጥሪ ሲልክ DireSkill ከስራ ዝርዝሮቹ ዲጂታል ሰርቪስ ውል ሰይሟሉ።",
    "faq.3.q": "ቻፓ ክፍያ እንዴት ይሰራል?",
    "faq.3.a": "ስራ ሲጠናቀቅ ደንበኛ በቻፓ ደህንነቱ ተጠብቆ ይከፍላሉ። ግብይቱ ከውሉ ጋር ይዛመዳሉ።",
    "faq.4.q": "ሰራተኞች ዋጋ ይደራደራሉ?",
    "faq.4.a": "አዎ። ሰራተኞች ቅጥር ጥሪ ከመፍጠሩ በፊት ዋጋ ዋይዋይ ሊያደርጉ ይችላሉ።",
    "faq.5.q": "ክርክር ቢፈጠር ምን ይሆናሉ?",
    "faq.5.a": "ሁለቱም ወገን ከውሉ ዝርዝሮቹ ላይ ክርክር ሊያቀርቡ ይችላሉ። አስተዳዳሪዎቻችን 48 ሰዓታት ውስጥ ውሳኔ ይሰጣሉ።",
    "faq.6.q": "ሰራተኞች ዝናቸውን እንዴት ያሳድጋሉ?",
    "faq.6.a": "ሁሉም ተጠናቅቆ የተከፈለ ስራ ደንበኛ ደረጃ ሊሰጥ ይፈቅዳሉ። ሰራተኞች ደረጃ ሲቆጠሩ ፕሮፋይሉ ይሻሻሉ።",

