    "testimonials.title": "MAAMILTOONNI KEENYA MAAL JADHU",
    "testimonials.subtitle": "Dirree Dawaa guutuutti amanamaa ta'uu, hojii milkaa'aa tokkoon tokkoon ijaarra.",

    "testimonial.1.name": "Ahmed Tasfaye",
    "testimonial.1.role": "Bulchaa Qabeenyaa",
    "testimonial.1.text": "DireSkill akkaataa ani gamoowwan koo itti bulchu guutummaatti jijjiireera. Hojjetaa boombii mirkanaa'e daqiiqaa muraasa keessatti argachuun lubbuu baraara.",
    "testimonial.2.name": "Muna Ibrahim",
    "testimonial.2.role": "Abbaa Manaa",
    "testimonial.2.text": "Hojjettoota yeroo qacaru nageenya kootiif nan yaadda'an ture. Amma mirkaneessaa eenyummaa fi waliigaltee dijitaalaatiin guutummaatti nageenya qaba.",
    "testimonial.3.name": "Dawit Berhanu",
    "testimonial.3.role": "Abbaa Hojii",
    "testimonial.3.text": "Qulqullinni ogeeyyii meeshaa kana irratti argaman wal-hin gitu. Gahumsa qabu, mirkanaa'aniiru, yeroo hundas kabaja qabu.",
    "testimonial.4.name": "Selamawit G.",
    "testimonial.4.role": "Bulchaa Supar-maarketiin",
    "testimonial.4.text": "Keziraa keessatti elektirishiyaanii argachuuf karaan saffisaa dha. Sadarkaan kennamu nama sirrii filachuuf gargaara.",
    "testimonial.5.name": "Yonas B.",
    "testimonial.5.role": "Abbaa Ristooraantii",
    "testimonial.5.text": "Hojiin xumura manaa ani DireSkill irraa argadhe baay'ee gaarii ture. Qulqulluu, ogeessaa fi yeroon kan xumuramedha.",
    "testimonial.6.name": "Hana T.",
    "testimonial.6.role": "Daarektara Mana Barumsaa",
    "testimonial.6.text": "Dhumarratti, bakka hojjettoonni itti mirkanaa'an arganneerra. Suphaa mana barumsaa keenya hundumaaf sammuu nagaa naaf kenna.",

    "cta.title": "HOJII KEE JIJJIIRUUF QOPHEESSAA?",
