    "faq.section_label": "GAAFFILEE",
    "faq.title": "Gaaffileetti deebii",
    "faq.subtitle": "Galmaa'uun dura wanti beekuu barbaaddan hunda.",
    "faq.1.q": "Mirkanneessuu Fayda ID akkamitti hojjata?",
    "faq.1.a": "Hojjetoonni galmee Itoophiyaa Fayda ID ol naquu. Gareen keenya sanadaa qorata. Mirkanaa'ee booda mallattoon piroofaayilii irratti mul'ata.",
    "faq.2.q": "Waliigaltee dijitaaloonni akkamitti uumamu?",
    "faq.2.a": "Maashaa baasaan yayyabaa erguu erga DireSkill waliigaltee dijitaalaa hojii odeeffannoo irraa ofumaan uuma.",
    "faq.3.q": "Kaffaltii Chapa akkamitti hojjata?",
    "faq.3.a": "Hojiin xumuraa erga maashaa baasaan Chapaan kafala. Waliigalteedhaan walitti qabama.",
    "faq.4.q": "Hojjetoonni gatii mariiachu ni danda'u?",
    "faq.4.a": "Eeyyee. Hojjetoonni ergaa app fayyadamuun gatii irratti mariiachu ni danda'u.",
    "faq.5.q": "Mormitin yoo uumame maaltu ta'a?",
    "faq.5.a": "Michootni lachuu waliigaltee irraa mormi kaasuu ni danda'u. Gareen keenya sa'aatii 48 keessatti murteessa.",
    "faq.6.q": "Hojjetoonni maqaa isaanii akkamitti fooyyeessu?",
    "faq.6.a": "Hojii hunda xumuraman maashaa baasaan sadarkaa kennuu ni danda'a. Hojjetoonni sadarkaa guddisu.",

